 SportsEventAuthoring.Box("Meadow surroundings",new Vector3(0,-.65f,90),new Vector3(200,1,300),grass,ground);SportsEventAuthoring.Box("Continuous racing course",new Vector3(0,-.3f,95),new Vector3(42,.6f,210),dirt,ground);for(int side=-1;side<=1;side+=2){SportsEventAuthoring.Box("Continuous outside rail",new Vector3(side*21.3f,.8f,95),new Vector3(.6f,1.6f,210),white,wall);for(int i=0;i<30;i++)SportsEventAuthoring.Box("Course scale reference",new Vector3(side*23,.8f,i*7-8),new Vector3(.2f,1.6f,.2f),amber);}
 var course=m.gameObject.AddComponent<TerrierCourse>();m.course=course;course.hurdles=new Transform[4];for(int i=0;i<4;i++){var g=SportsEventAuthoring.Box("Rounded hurdle "+i,new Vector3(0,.25f,32+i*27),new Vector3(40,.5f,.4f),white,ground);course.hurdles[i]=g.transform;}course.ramps=new Transform[6];for(int i=0;i<6;i++)course.ramps[i]=SportsEventAuthoring.Box("Gentle jump ramp "+i,new Vector3((i%3-1)*11,.35f,44+i/3*55),new Vector3(8,.25f,6),white,ground).transform;course.patches=new Transform[6];for(int i=0;i<6;i++)course.patches[i]=SportsEventAuthoring.Box("Mud terrain patch "+i,new Vector3((i%3-1)*12,.015f,55+i/3*54),new Vector3(8,.025f,10),grass).transform;
