 course.finish=new GameObject("Full-width finish wall and single legal tunnel").transform;course.finish.position=new Vector3(0,0,168);float width=(42-TerrierRules.TunnelHalfWidth*2)*.5f;for(int side=-1;side<=1;side+=2){var g=SportsEventAuthoring.Box("Solid finish barrier",new Vector3(side*(TerrierRules.TunnelHalfWidth+width*.5f),3,TerrierRules.TunnelDepth*.5f),new Vector3(width,6,TerrierRules.TunnelDepth),dark,wall,course.finish);g.AddComponent<TerrierFinishWall>();SportsEventAuthoring.Box("Tunnel side trim",new Vector3(side*(TerrierRules.TunnelHalfWidth+.08f),TerrierRules.TunnelHeight*.5f,-.04f),new Vector3(.16f,TerrierRules.TunnelHeight,.08f),amber,null,course.finish);}var lintel=SportsEventAuthoring.Box("Solid finish lintel",new Vector3(0,(6+TerrierRules.TunnelHeight)*.5f,TerrierRules.TunnelDepth*.5f),new Vector3(TerrierRules.TunnelHalfWidth*2,6-TerrierRules.TunnelHeight,TerrierRules.TunnelDepth),dark,wall,course.finish);lintel.AddComponent<TerrierFinishWall>();SportsEventAuthoring.Box("Finish tunnel roof trim",new Vector3(0,TerrierRules.TunnelHeight+.08f,-.04f),new Vector3(TerrierRules.TunnelHalfWidth*2+.32f,.16f,.08f),amber,null,course.finish);var sign=SportsEventAuthoring.Label("Finish hole sign","THROUGH HERE",new Vector3(0,4.4f,167.9f),.3f,Color.white);sign.transform.SetParent(course.finish,true);sign.transform.rotation=Quaternion.identity;
 var scenery=new GameObject("Terrier course installed scenery").transform;for(int i=0;i<42;i++){var p=new Vector3((i%2==0?-1:1)*(29+i%5*5),0,i/2*10-15);LWS.TruckBaseJumping.Editor.BaseSkyAuthoring.Scenery(scenery,p,i%4==0?3:7+i%4,i%4!=0,Folder);}m.racers=new TerrierRacer[12];m.replay=m.gameObject.AddComponent<TerrierReplay>();m.replay.match=m;m.replay.ghosts=new Transform[12];m.replay.bursts=new ParticleSystem[12];m.blasts=new ParticleSystem[8];var flare=SportsChaosAuthoring.Flare(Folder);for(int i=0;i<12;i++){var truck=SportsEventAuthoring.Truck(m,Folder,"Terrier competitor "+(i+1),new Vector3((i-5.5f)*3.3f,.48f,0),i);truck.maxSpeed=22;truck.motorTorque=8;truck.steerAngle=38;truck.body.centerOfMass=new Vector3(0,-.08f,0);truck.body.maxAngularVelocity=10;truck.body.maxLinearVelocity=36;var racer=truck.gameObject.AddComponent<TerrierRacer>();racer.match=m;racer.truck=truck;racer.slot=i;m.racers[i]=racer;FitPhysicalTruck(racer);foreach(var t in truck.visuals.GetComponentsInChildren<Transform>(true))t.gameObject.layer=10+i;
 var ghost=new GameObject("Recorded visual ghost "+i);var art=UnityEngine.Object.Instantiate(truck.visuals.gameObject,ghost.transform,false);foreach(var t in art.GetComponentsInChildren<Transform>(true)){t.gameObject.layer=0;foreach(var component in t.GetComponents<Component>())if(!(component is Transform)&&!(component is Renderer)&&!(component is MeshFilter))UnityEngine.Object.DestroyImmediate(component);}m.replay.ghosts[i]=ghost.transform;ghost.SetActive(false);var fx=new GameObject("Recorded visual explosion "+i).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(fx,flare);m.replay.bursts[i]=fx;if(i<8){fx=new GameObject("Pooled heat explosion "+i).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(fx,flare);m.blasts[i]=fx;}}
