 m.menus.header.transform.parent.GetComponent<RectTransform>().sizeDelta=new Vector2(1880,48);m.menus.header.transform.parent.GetComponent<RectTransform>().anchoredPosition=new Vector2(0,510);m.menus.header.fontSizeMax=24;m.menus.header.rectTransform.sizeDelta=new Vector2(1800,40);m.menus.standings.rectTransform.anchoredPosition=new Vector2(0,-435);m.menus.standings.rectTransform.sizeDelta=new Vector2(1800,100);m.menus.standings.alignment=TMPro.TextAlignmentOptions.Center;m.menus.standings.fontSizeMax=21;m.menus.status.rectTransform.anchoredPosition=new Vector2(0,-510);m.menus.status.fontSizeMax=23;foreach(var label in m.menus.viewTexts){label.rectTransform.sizeDelta=new Vector2(780,85);label.fontSizeMax=23;label.fontSizeMin=18;label.transform.parent.Find("View data backing").GetComponent<RectTransform>().sizeDelta=new Vector2(800,105);}
 SportsEventAuthoring.Save(Folder);Validate();}
 public static void FitPhysicalTruck(TerrierRacer racer){var truck=racer.truck;var binding=truck.GetComponent<TerrierWheelPresentation>();if(binding==null)binding=truck.gameObject.AddComponent<TerrierWheelPresentation>();binding.racer=racer;binding.meshes=new Transform[4];binding.centers=new Vector3[4];binding.alignment=new Quaternion[4];string[] names={"Whl HD FL","Whl HD FR","Whl HD RL","Whl HD RR"};for(int i=0;i<4;i++){var mesh=truck.visuals.GetComponentsInChildren<MeshFilter>(true).First(f=>f.name==names[i]);var renderer=mesh.GetComponent<Renderer>();mesh.transform.localScale*=truck.wheels[i].wheel.radius/Mathf.Max(.01f,BoundsInTruck(mesh,truck.transform).extents.y);binding.meshes[i]=mesh.transform;binding.centers[i]=mesh.sharedMesh.bounds.center;binding.alignment[i]=Quaternion.Inverse(truck.wheels[i].wheel.rotatingContainer.rotation)*mesh.transform.rotation;}
 var bounds=new Bounds();bool first=true;foreach(var renderer in truck.visuals.GetComponentsInChildren<Renderer>(true)){var filter=renderer.GetComponent<MeshFilter>();if(filter==null||filter.sharedMesh==null)continue;var local=BoundsInTruck(filter,truck.transform);if(first){bounds=local;first=false;}else bounds.Encapsulate(local);}truck.shape.center=bounds.center;truck.shape.size=bounds.size;EditorUtility.SetDirty(binding);EditorUtility.SetDirty(truck.shape);}
 static Bounds BoundsInTruck(MeshFilter filter,Transform truck){var source=filter.sharedMesh.bounds;Bounds bounds=default;for(int i=0;i<8;i++){var p=truck.InverseTransformPoint(filter.transform.TransformPoint(source.center+Vector3.Scale(source.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));if(i==0)bounds=new Bounds(p,Vector3.zero);else bounds.Encapsulate(p);}return bounds;}
 public static void OpenGateArt(Transform gate,Material amber){gate.GetComponent<Renderer>().enabled=false;if(gate.Find("Open gate bars")!=null)return;var root=new GameObject("Open gate bars").transform;root.SetParent(gate,false);for(int i=0;i<3;i++)SportsEventAuthoring.Box("Gate crossbar",new Vector3(0,(i-1)*.35f,0),new Vector3(1,.035f,1),amber,null,root);for(int side=-1;side<=1;side+=2)SportsEventAuthoring.Box("Gate upright",new Vector3(side*.48f,0,0),new Vector3(.035f,1,1),amber,null,root);}
 public static void PolishSaved(){EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<TerrierMatch>();var amber=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckTerrierRacing/Materials/Tunnel gold.mat");foreach(var gate in m.course.gates)OpenGateArt(gate,amber);for(int i=0;i<12;i++){FitPhysicalTruck(m.racers[i]);var root=m.replay.ghosts[i];foreach(Transform child in root)UnityEngine.Object.DestroyImmediate(child.gameObject);var art=UnityEngine.Object.Instantiate(m.racers[i].truck.visuals.gameObject,root,false);foreach(var t in art.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;}foreach(var c in m.cabViews)SportsChaosAuthoring.Cab(c.view,Folder,Array.IndexOf(m.cabViews,c),25);TerrierCourseArtAuthoring.Install(m);TerrierRouteAuthoring.Install(m);TerrierTunnelAuthoring.Install(m);StageTrucks(m);TerrierAtmosphereAuthoring.Install(m);TerrierCrowdAuthoring.Install(m);TerrierCountdownAuthoring.Install(m);TerrierWreckAuthoring.Install(m);TerrierDessertAuthoring.Install(m);m.replay.capacity=2200;var sign=m.course.finish.Find("Finish hole sign");if(sign!=null)sign.localRotation=Quaternion.identity;EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();}
 static void StageTrucks(TerrierMatch m){for(int i=0;i<12;i++)m.racers[i].transform.SetPositionAndRotation(m.course.StartPosition(i,1),m.course.DrivingRotation);}
 public static void Validate(){Fixtures();EditorSceneManager.OpenScene(Scene);var m=UnityEngine.Object.FindAnyObjectByType<TerrierMatch>();if(m==null||m.racers.Length!=12||m.setup.players.Length!=12||m.menus.names.Length!=12||m.replay.ghosts.Length!=12||m.cabViews.Length!=4||m.course.weather.vendor==null||m.crowd==null||m.crowd.runners.Length!=10||m.snow==null||m.countdown==null||m.countdown.panels.Length!=4||!m.course.Valid())throw new Exception("Terrier saved references incomplete");foreach(var g in m.replay.ghosts)if(g.GetComponentsInChildren<Collider>(true).Length>0||g.GetComponentsInChildren<Rigidbody>(true).Length>0)throw new Exception("Replay must be visual only");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One shared audio listener required");TerrierVolcanoAuthoring.ValidateAtmosphere(m);Debug.Log("TERRIER_SAVED_VALIDATED twelve physical racers, four human cameras, nonphysical ghosts");}
 public static void Fixtures(){int n=0;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Terrier fixture: "+label);n++;};var state=new TerrierTunnelState();float entrance=100;var a=new Bounds(new Vector3(0,.5f,97),new Vector3(1.2f,.65f,2.7f));var b=new Bounds(new Vector3(0,.5f,100),a.size);check(!TerrierRules.Crossing(ref state,a,b,entrance,out _)&&state.entered,"front enters but not finished");a=b;b.center=new Vector3(0,.5f,105);check(TerrierRules.Crossing(ref state,a,b,entrance,out var fraction)&&fraction>0&&fraction<1,"rear completely exits");check(!TerrierRules.Crossing(ref state,a,b,entrance,out _),"no repeated finish");state=default;a.center=new Vector3(5,.5f,97);b.center=new Vector3(5,.5f,105);check(!TerrierRules.Crossing(ref state,a,b,entrance,out _),"side bypass rejected");state=default;a.center=new Vector3(0,6,97);b.center=new Vector3(0,6,105);check(!TerrierRules.Crossing(ref state,a,b,entrance,out _),"above-wall bypass rejected");check(TerrierRules.FatalWall(new Vector3(0,0,15),Vector3.back)&&!TerrierRules.FatalWall(new Vector3(15,0,2),Vector3.back),"wall-normal speed distinguishes impact and graze");var times=Enumerable.Repeat(float.PositiveInfinity,12).ToArray();times[4]=10;times[9]=10;check(TerrierRules.Winner(times)==-1,"true tie no point");times[9]=10.01f;check(TerrierRules.Winner(times)==4,"earliest timestamp wins");var stalls=new bool[12];for(int heat=0;heat<12;heat++)stalls[TerrierRules.Stall(0,heat)]=true;check(stalls.All(value=>value),"every stall visited in twelve heats");Debug.Log("TERRIER_RULE_FIXTURES_PASS count="+n);}
